## One segment of the surreal chip bar: selection ring + per-spin fill overlay.

signal segment_pressed(index: int)

@export var segment_index: int = 0

var fill_ratio: float = 0.0:
	set(value):
		fill_ratio = clampf(value, 0.0, 1.0)
		queue_redraw()

var _selected: bool = false
var _fill_tween: Tween


func _ready() -> void:
	focus_mode = Control.FOCUS_NONE
	toggle_mode = false
	flat = true
	text = ""
	custom_minimum_size = Vector2(28, 36)
	pressed.connect(_on_pressed)
	mouse_entered.connect(queue_redraw)
	mouse_exited.connect(queue_redraw)


func set_selected(active: bool) -> void:
	_selected = active
	queue_redraw()


func animate_fill(target_ratio: float, duration: float = 0.2) -> void:
	_kill_fill_tween()
	var from_ratio := fill_ratio
	if duration <= 0.0:
		fill_ratio = target_ratio
		return
	_fill_tween = create_tween()
	_fill_tween.set_trans(Tween.TRANS_SINE).set_ease(Tween.EASE_OUT)
	_fill_tween.tween_method(_set_fill_ratio, from_ratio, clampf(target_ratio, 0.0, 1.0), duration)


func reset_fill() -> void:
	_kill_fill_tween()
	fill_ratio = 0.0


func _set_fill_ratio(value: float) -> void:
	fill_ratio = value


func _on_pressed() -> void:
	segment_pressed.emit(segment_index)


func _draw() -> void:
	var rect := Rect2(Vector2.ZERO, size)
	var base := Color(0.12, 0.01, 0.01, 0.92)
	var edge := Color(0.55, 0.04, 0.04, 0.85)
	if _selected:
		edge = Color(1.0, 0.2, 0.2, 1.0)
		base = Color(0.22, 0.02, 0.02, 0.98)
	draw_rect(rect, base, true)
	draw_rect(rect, edge, false, 2.0)
	if fill_ratio > 0.0:
		var fill_h := rect.size.y * fill_ratio
		var fill_rect := Rect2(rect.position.x + 2.0, rect.position.y + rect.size.y - fill_h - 2.0, rect.size.x - 4.0, fill_h)
		draw_rect(fill_rect, Color(0.95, 0.08, 0.08, 0.88), true)
	if _selected:
		draw_arc(rect.position + rect.size * 0.5, min(rect.size.x, rect.size.y) * 0.55, 0.0, TAU, 24, Color(1.0, 0.45, 0.45, 0.35), 2.0)


func _kill_fill_tween() -> void:
	if _fill_tween != null and is_instance_valid(_fill_tween):
		_fill_tween.kill()
	_fill_tween = null

