func _build_chip_bar() -> void:
	_chip_segments.clear()
	var section_count := combat.get_chip_bar_section_count()
	for i in section_count:
		var seg := ChipBarSegmentScript.new()
		seg.segment_index = i
		seg.segment_pressed.connect(_on_chip_segment_pressed)
		_chip_bar_row.add_child(seg)
		_chip_segments.append(seg)
	_refresh_chip_selection()


func _refresh_chip_selection() -> void:
	for i in _chip_segments.size():
		var seg := _chip_segments[i] as ChipBarSegmentScript
		if seg != null:
			seg.set_selected(i == _selected_chip_index)


func _refresh_chip_bar_health() -> void:
	var health := combat.get_chip_bar_health_ratio()
	var per_section := health * float(combat.get_chip_bar_section_count())
	for i in _chip_segments.size():
		var seg := _chip_segments[i] as ChipBarSegmentScript
		if seg == null:
			continue
		if i == _selected_chip_index:
			continue
		var section_fill := clampf(per_section - float(i), 0.0, 1.0)
		seg.fill_ratio = section_fill


func _reset_chip_fills_for_spin() -> void:
	for seg in _chip_segments:
		if seg is ChipBarSegmentScript and seg.segment_index == _selected_chip_index:
			seg.reset_fill()


func _animate_selected_chip_fill(win_ratio: float) -> void:
	for seg in _chip_segments:
		if seg is ChipBarSegmentScript and seg.segment_index == _selected_chip_index:
			var fill := clampf(win_ratio, 0.0, 1.0)
			seg.animate_fill(fill, 0.25)


func _refresh_items_panel() -> void:
	for child in _items_list.get_children():
		child.queue_free()
	var equipped: Array = combat.inventory.items
	for item in equipped:
		var tile := MatchedLogTileScript.new()
		var icon_tex: Texture2D = item.get("icon") if item != null else null
		tile.set_symbol_texture(icon_tex)
		tile.tooltip_text = "%s\n%s" % [item.display_name, item.description]
		_items_list.add_child(tile)
	var placeholders_needed := maxi(ITEM_PLACEHOLDER_COUNT - equipped.size(), 0)
	for _i in placeholders_needed:
		var ph := PanelContainer.new()
		ph.custom_minimum_size = Vector2(36, 36)
		var ph_style := StyleBoxFlat.new()
		ph_style.bg_color = Color(0.05, 0.0, 0.0, 0.5)
