		ph_style.set_border_width_all(1)
		ph_style.set_corner_radius_all(4)
		ph.add_theme_stylebox_override("panel", ph_style)
		_items_list.add_child(ph)
	if _items_header != null:
		_items_header.text = "ITEMS (%d)" % equipped.size()


